package com.example.smartpantrymanager.ui;
import android.app.*;import android.content.*;import android.os.*;import android.view.*;import android.widget.*;import androidx.appcompat.app.AppCompatActivity;import androidx.recyclerview.widget.*;import com.example.smartpantrymanager.R;import com.example.smartpantrymanager.adapter.PantryAdapter;import com.example.smartpantrymanager.data.DatabaseHelper;import com.example.smartpantrymanager.model.PantryItem;import java.util.*;
public class MainActivity extends AppCompatActivity implements PantryAdapter.Listener{
 DatabaseHelper db;PantryAdapter adapter;RecyclerView rv;TextView empty;
 @Override protected void onCreate(Bundle b){super.onCreate(b);setContentView(R.layout.activity_main);db=new DatabaseHelper(this);rv=findViewById(R.id.recyclerPantry);empty=findViewById(R.id.emptyText);rv.setLayoutManager(new LinearLayoutManager(this));adapter=new PantryAdapter(new ArrayList<>(),this);rv.setAdapter(adapter);findViewById(R.id.btnAdd).setOnClickListener(v->startActivity(new Intent(this,AddEditIngredientActivity.class)));findViewById(R.id.btnSuggest).setOnClickListener(v->startActivity(new Intent(this,SuggestedRecipesActivity.class)));findViewById(R.id.btnSettings).setOnClickListener(v->startActivity(new Intent(this,SettingsActivity.class)));}
 @Override protected void onResume(){super.onResume();load();}void load(){List<PantryItem> l=db.getPantry();adapter.setData(l);empty.setVisibility(l.isEmpty()?View.VISIBLE:View.GONE);}
 public void edit(PantryItem p){Intent i=new Intent(this,AddEditIngredientActivity.class);i.putExtra("id",p.getId());startActivity(i);}public void delete(PantryItem p){new AlertDialog.Builder(this).setTitle("Delete ingredient?").setMessage("Remove "+p.getName()+" from your pantry?").setPositiveButton("Delete",(d,w)->{db.deletePantry(p.getId());load();}).setNegativeButton("Cancel",null).show();}
}
